namespace ByteEngine.Editor.Assistant;

// Engine-specific recipes, retrieved only when relevant to keep prompts small.
internal static class AssistantKnowledge
{
    private static readonly (string Topic, string Guide)[] Guides =
    [
        ("hazard pay mining refinery ammo press economy operation raider damage attack slots", "Inspect the current project and loaded Mining components; do not assume the old hunt/Crownback setup. Hazard Pay uses MiningOperation3D, MiningTrade3D and editable .byteai spider roles. Operation HunterDamage/RaiderDamage and HunterAttackSlots/RaiderAttackSlots expose per-hit pressure and simultaneous attackers; contract multipliers apply once. More enemies can increase aggregate damage without a hidden operation-three damage multiplier. RefineryBaseCost/SpeedBaseCost/YieldBaseCost and RefineryCostGrowth tune refinery ranks separately from drill growth. Press OutputCost/StorageCost/EfficiencyCost and UpgradeCostGrowth tune prices. For UseProductionCycles=true, BaseCycleSeconds and CycleSecondsReductionPerLevel control cycle time; BaseRoundsPerCycle and ExtraRoundsPerCycle control payload, independent of speed. ProductionCycleProgress exposes progress. Hazard Pay starts at 5 rounds per 5 seconds with 35 storage. Refinery QueueRefineryBatches processes 3 ore every 3 seconds in the background; LinearRefinerySpeedUpgrades subtracts .25 seconds per speed rank. AutomaticDefeatRecovery fades to black, returns to initial/custom RecoverySpawnPosition, revives and fades in. See byte_reference HazardPay-Workshop-Balance. Read current component values and saved ranks before changing balance; do not reset progress. See byte_reference HazardPay-PC-Polish-2026-10-29 and the exact loaded plugin sources."),
        ("spider bullets hitbox trigger projectile recoil accuracy off target collision", "Damage hitboxes must match visible bodies without enlarging movement capsules. MiningSpiderAnimation3D exposes BodyHitboxEnabled, BodyHitboxSize and BodyHitboxCenter; its trigger child uses DamageRegion3D.IsWeakPoint=false. True weak points keep IsWeakPoint=true. GameplayQuery3D.RaycastWithDamageHits can include damage regions while excluding pickup triggers; ordinary solid queries retain their original API. Gun projectiles ignore nondamage pickup trigger volumes. WeaponInstance3D.RecoiledDirection is shared by shooting and the third-person reticle. AccuracyDegrees, MovingInaccuracyDegrees, SpreadDegrees and bloom remain editable weapon stats; accuracy is not guaranteed merely because a reticle is visible. Inspect actual colliders, masks, muzzle points and recoil before adding aim assist or enlarging hitboxes."),
        ("menu music hover notification confirmation overlap arrange camp ui", "MiningAudio3D music fades use Time.UnscaledDeltaTime so paused main menus can play CampMusic. Music is routed to AudioBus.Music; menu hover uses PlayHoverCue with configurable HoverSoundGain and fires once on pointer entry. MiningPauseMenu3D and MiningBusinessUi3D expose gain. Permanent upgrade feedback has a dedicated map/details separator strip; do not overlay description/rank/button text. Camp arrangement uses compact header/footer/nameplates. Inspect current UI ownership and native button/event links before adding another interface. Preserve exact upgrade effects, current/next values, costs, prerequisite and purchase feedback. Validate rendered Windows screenshots, not compilation alone."),
        ("character explorer skeleton rig animation retarget bind pose bone weights model swap", "Imported custom characters require the source armature's exact bone names, hierarchy, rest transforms, axes, units and inverse bind relationship. Reusing an unchanged supplied armature avoids guessing compatibility; mesh weights still require animation tests. Preserve existing action/clip names, SH/DH blendspaces, upper-body layers and per-weapon sockets. Inspect the Model and AnimationProfile references before swapping visuals; do not replace gameplay roots or duplicate controllers. Test walk/run/strafe, shoot/reload and death, including hand/socket alignment and bounds. Native assistant tools can inspect/bind imported assets, but cannot sculpt or automatically rig a complex character; report external-authoring limits honestly. See byte_reference Weapon-Locomotion and Model-Attachment-Points."),
        ("windows release runtime dll exposed security single file native aot export", "Desktop games must ship executable engine code. Visible .NET runtime dependencies are not source files, but managed engine DLLs can be decompiled. Bundling hides clutter, not code; an embedded decryption key cannot guarantee secrecy. ByteEngine's reflection codecs and dynamically loaded plugins mean Native AOT is a migration, not a publish-flag fix. Never remove Runtime files manually, promise unextractable clients, expose editor/assistant credentials, reset saves, or export without explicit authorization. Prefer clean release audits, no source/PDB/editor artifacts, signing/integrity checks, then a separately tested bundling/obfuscation strategy. See byte_reference Windows-Release-Protection."),
        ("web browser performance capture profiling allocation optimization fps", "Shared Core/browser optimizations include bounded transfer buffers, binary draw/UI packets, render ancestry/bounds invalidation, used-bone and rigid-part skinning, immutable blueprint template preparation and reusable A* scratch. They preserve quality, not a universal FPS guarantee. Deep profiling adds overhead: compare normal warmed captures at identical scene/camera/resolution and exclude menus/uploads. The release gate can reject a running game below 30 FPS or with frame errors. Existing exports do not update when engine runtime files change; plugin version/hash mismatches require refreshing the static browser runtime, not silently ignoring validation. Read Web-Performance-Capture and Shared-Runtime-Performance-2026-10-28 before claiming a bottleneck is solved."),
        ("ai behavior behaviour enemy tree blackboard squad staged combat", "AI Behaviour is a native .byteai asset with a WHEN/DO editor. Inspect the target enemy and existing asset first; byte_inspect asset=path reads .byteai, byte_catalog kind=asset_types search=AI gives the exact schema. create_ai_behavior can use Basic, AttackStages, Melee, Flanker, Ranged, Caster, Charger or Boss presets, source=existingAIPath to make a NEW editable variant, or tree=nativeDefinition for custom logic. Presets inline stages unless sharedAttack names an existing .byteai or an earlier $asset: alias. Typical reusable setup: create AttackStages asset, create a role asset with sharedAttack=$asset:Attack, then set AIBehavior3D.Behavior=$asset:Role. Keep SimpleEnemyAI3D ENABLED with BehaviorControlled=true for staged attacks; its autonomous update is skipped. AIBehavior3D.PerceptionMemory=true enables sight/hearing memory. Bind TargetObjectId or enable FindNearestCharacter. Ensure enabled NavigationAgent3D bound to a baked NavigationRegion3D, initially ExternallyDriven=false; the behaviour takes ownership while moving. Do not blindly disable the combat component: that is the encounter activation gate. Basic/custom trees without native combat stages may disable Simple Enemy AI instead. Inspect/edit existing components instead of adding competing drivers. Discover the current project role and shared-attack assets; do not assume an old hunt or boss setup still exists. Do not replace existing encounter rules or reset tuning unless requested. See byte_reference AI-Perception-Tactics-and-Combat."),
        ("perception hearing sight memory search last known noise alerted", "AIBehavior3D exposes PerceptionMemory, DetectionRange, FieldOfView, EyeHeight, SightMaskBits, MemorySeconds, HearingRange, HearingMemorySeconds and OccludedHearingMultiplier. An explicit target is a perception candidate, not wall vision. With memory enabled, TargetPosition/LastKnownPosition stop following an unseen actor; HasMemory expires. Built-in keys include HasTarget, HasLineOfSight, HasMemory, HeardNoise, HealthFraction, TargetDistance, TargetPosition, LastKnownPosition, AttackPhase, EvadedCharges, EvadedSlams, IsDodging and IsEnraged. Use a LineOfSight gate for attacks and HasMemory gate for Search. Hearing uses explicit noise events; gunshots emit from their muzzle through WeaponDefinition3D.NoiseRadius (0 silent). Use catalogue action ai.noise for footsteps/alarms, ai.forget to clear interest; do not assume every Audio Source automatically emits AI noise. Search is bounded by duration/memory and uses navigation. Sight is cone+ray; this is not an acoustic simulator."),
        ("tactics cover flank surround firing lane position coordination reservation", "Choose tactical position is BehaviorNodeKind.FindPosition with PositionKind Cover, FiringLane, Flank or Surround. It stores a reachable point in Key (e.g. CombatPoint); follow with MoveToPoint using the same Key. Distance, SearchRadius, Spacing and Duration tune preferred range, candidates and holding. Queries check reachability, visibility and scene-local reserved spacing; Navigation Region must be baked. Set AIBehavior3D.Squad, MaximumAttackers and PositionSpacing. ReserveAttack waits for capacity; ReleaseAttack and ReleasePosition relinquish ownership. Pause/death/inactive actors release or prune leases. PositionQueryInterval, PositionCandidates, PositionPathsPerQuery and PositionVisitedBudget bound cost; do not increase all budgets to hide a failed binding. This distributes destinations, not a full predictive crowd solver. Current hunt has a two-attacker normal squad and separate one-attacker boss squad."),
        ("combat stages telegraph commit strike recovery subbehavior service interruption decision history", "Staged combat order is ReserveAttack -> ChooseAttack -> Telegraph -> CommitAttack -> Strike -> Recover (movement/approach belongs before reservation). Native SimpleEnemyAI3D supplies windup, recovery, damage, projectile/fireball and charge/slam implementations. Automatic attack choice preserves the adaptive chooser; explicit Slam/Feint require AdaptiveBoss and Charge requires Charger style. Never add an extra damage event to the native strike. Stage signals AttackChosen, AttackTelegraph, AttackCommitted, AttackStrike and AttackRecovery can drive presentation through ai.signal. Gate/Priority Interruption supports Recheck, FinishBranch and FinishCommittedAttack; committed attacks keep locked aim. SubBehavior calls an existing .byteai with shared blackboard but isolated call-site execution; recursion is rejected. Services have enabled/name/kind/interval/key plus HealthFlag, SetMemory, Signal or PositionQuery settings and run during waits. Test / Live view shows bounded decision reasons and JSON Export history. Build/property inspection is not a gameplay test; do not claim runtime validation without actual evidence."),
        ("weapons gun projectile bullet trail muzzle flash pickup inventory recoil socket", "Weapons use Modular Weapon Gameplay components: Weapon Equipment (FpsGunLab3D) on player; WeaponDefinition3D, WeaponInstance3D and WeaponPickup3D on the imported gun MODEL ROOT for a self-contained world pickup. Pickup WeaponObjectId empty means itself, no inventory parenting is needed. DefaultWeaponObjectId chooses starting gun; StartWithNoWeapons and CarryLimit control loadout (0 unlimited). Definition owns damage/capacity/rate/reload/accuracy/recoil; Instance owns remaining ammo. Distinct Definition.Slot values are required, while carried-position hotkeys use equipInventoryIndex. Gun ShotMode=Projectile uses swept physical bullets; empty ProjectileBlueprint gives standard bullets. ProjectileSpeed/Radius/VisualSize/Lifetime/MaxActiveProjectiles and ProjectileTrailLength/TraceWidth are editable. ShowShotTrace enables the bright tapered core/glow trail; TrailCoreColor, TrailGlowColor, TrailGlowScale, TrailBrightness, TrailImpactFadeSeconds expose appearance. Hits arrive later: Weapon fired is for launch presentation, Weapon shot hit is for actual impact; do not double-apply damage. MuzzleSource=NamedModelPoint uses a visually authored barrel point from double-click model -> Add empty point. Assigned MuzzleObjectId overrides the point. GripSocket aligns hands, not the muzzle; LocomotionBlendSpace chooses One Hand/Two Hand. Audio and gun animation remain editable event sheets. WeaponInventoryHud3D displays only carried guns and segmented reserve magazines; reserve counts rounds, each marker is one magazine worth. Discover exact loaded plugin actions with byte_catalog, and see byte_reference Weapon-Setup-Tutorial / Gun-Projectiles-and-Trails / Model-Attachment-Points."),
        ("top down top-down duckov isometric overhead cursor twin stick camera controller", "Native Duckov-style top-down setup: reuse CharacterController3D and CapsuleCollider3D on the player root, add TopDownController3D. Disable existing PlayerController3D (Enabled=false) to avoid competing movement/facing. Create a SEPARATE camera object with Camera3D.ActiveGameCamera=true and TopDownCamera3D.TargetId=@player; set TopDownController3D.CameraObjectId=@camera. Disable/remove old camera drivers (CameraBoom3D, FirstPersonCamera3D, ThirdPersonCamera3D) if they control that camera. CameraRelativeMovement=true makes WASD follow camera orientation; false matches original world-space Duckov input. Facing=Cursor turns smoothly to visible cursor while moving independently; Movement faces travel direction. TopDownCamera3D exposes Orthographic, Yaw, Pitch, Distance, OrthographicWidth, TargetHeight, FollowSharpness, CursorLookAhead, LookAheadDistance/dead zone/sharpness, wheel zoom limits and optional XZ bounds. True isometric: Orthographic=true,Yaw=45,Pitch=35.26439. CharacterController3D.MoveSpeed/Acceleration/Deceleration own speed; top-down does not override these. Optional sprint uses native character.setMoveSpeed events in the SAME Player Movement sheet. Event categories Top Down / Controller and Top Down / Camera expose input/facing/movement-space, aim-point output, camera target, look-ahead, zoom, snap and isometric preset. Add floor collider. Camera needs Camera3D; top-down rig alone cannot render. Input uses existing Move action; visible cursor stays free, click Game View to activate, Escape releases input. Use byte_animations for character animation setup; motor drives native locomotion."),
        ("camera third person movement player cube", "Playable third-person cube: inspect existing objects first. Player root needs MeshRenderer (Cube), CharacterController3D (movement/collision motor), CapsuleCollider3D (solid character shape), PlayerController3D (input/facing) and CameraBoom3D (camera positioning). Create a separate child object under the player with Camera3D; set Camera3D.ActiveGameCamera=true. Set root CameraBoom3D.CameraObjectId to that child GUID, or @createdCameraName in the same apply batch. CameraBoom3D requires its camera to be a DESCENDANT of the player. UseControlRotation=true uses PlayerController3D control yaw/pitch. Do not also add ThirdPersonCamera3D or FirstPersonCamera3D: competing camera owners cause conflicts. Inspect motor capsule dimensions and ground position; provide solid ground with a collider. Default Move/Look/Jump/Sprint input actions are used; verify current project input bindings from context. Preview requires Play and captured gameplay input. Verify active camera and links after applying; report that gameplay still needs a Play test."),
        ("camera follow orbit", "For a simple camera following an object without a playable controller, put Camera3D AND ThirdPersonCamera3D on a separate camera object. Set ThirdPersonCamera3D.TargetId to the target GUID (or @createdTargetName), or TargetName to a unique target name. Set Camera3D.ActiveGameCamera=true. Distance/Pitch/Height/LookAtHeight/ShoulderOffset control framing. This component reads Look directly. It is an alternative to CameraBoom3D, not an additional camera driver. A rendered camera needs Camera3D; a follow component alone does not render."),
        ("input controls keyboard mouse movement", "Project InputMap defines named actions and bindings. Context includes the actual map. PlayerController3D reads Move, Look, Jump and Sprint; CharacterController3D alone does not read WASD. Editable InputActionReference properties accept an action name string via set_property. GameplayEnabled/captured input can suppress input while menus are open. Raw key/mouse event conditions and named input actions are separate systems; use byte_catalog for exact IDs and argument defaults. V1 cannot edit project input-map bindings; explain this limitation rather than pretending to rebind them."),
        ("events conditions actions variables logic", "EventModuleComponent attaches editable .byteevents modules to objects. byte_apply add_event_rule creates or appends to the same descriptively named attached sheet; it preserves existing rows and supports Undo. Conditions on each new rule are AND; actions execute in order. system.always is a per-update condition, not a one-shot startup trigger. Catalogue exact IDs/arguments first. Self targets the event owner. Object references need explicit object targeting; do not assume an event on one object edits another. Constants use JSON; Vector2/3 arguments accept arrays. Use native EventValue references for changing values. Nested logic and existing-rule rewriting are unsupported; requested object deletion and reparenting are available."),
        ("physics collider rigidbody ground movement", "A visible MeshRenderer is not collision. Ground/obstacles need colliders. CharacterController3D owns kinematic character motion and uses a capsule; do not simultaneously drive it through dynamic Rigidbody motion or per-frame transform teleports. Catalogue dimensions/defaults before configuring. Visual scale and motor capsule dimensions must agree. Put the character above the ground rather than intersecting it. Scene edits and component wiring do not prove runtime movement or collision; request a Play test."),
        ("animation locomotion mannequin idle walk run character profile clips", "For a model character, call byte_animations target=$selected FIRST. It reads actual model-owned clip names/durations and rig from native AssetManager, including descendants, without guessing animations.json files. create_animation_profile data:{name,path:'Assets/Animations/Character.byteanim',model:returnedPath,locomotion:{Idle:exactName,Walk:exactName,Run:exactName,RunThreshold:4,RootMotionMode:'InPlace'}} saves an editable native profile; omitted slots are auto-discovered. Add/reuse AnimationController on the player root with AnimationProfile=$asset:name and DriveLocomotion=true. AnimationController creates skeletal playback on descendant ModelHierarchyInstance and disables its static bind-pose meshes at runtime. Do NOT manually duplicate SkeletalMeshRenderer; the authoring scene can legitimately show only MeshRenderer. Reuse the player's existing motor/input/camera. PlayerController3D's SprintAction is only a reference; it does not itself change speed. For walk/run controls, set initial CharacterController3D.MoveSpeed=2 and expose native event rules input.actionHeld {action:'Sprint'} -> character.setMoveSpeed {speed:6}, and input.actionReleased {action:'Sprint'} -> character.setMoveSpeed {speed:2}. Idle is automatic when stationary. Keep RunThreshold between walk and run speeds. Use sheet: Player Movement on BOTH add_event_rule operations, with descriptive names Sprint held - run and Sprint released - walk. Related rules share one sheet; never combine mutually exclusive triggers in one AND row. Reuse existing sprint sheets and events if present. Native profiles also accept sections for Actions/BlendSpaces/Layers/SyncGroups/StateGraph/Procedural. Clip names must exist on the reference rig; this does not retarget incompatible animations."),
        ("assets animation audio materials plugins", "byte_animations discovers model-owned clips; byte_catalog assets searches current project assets; components/actions/conditions include registered loaded plugins. Use exact returned paths and identifiers. AssetReference properties require existing project-relative paths. Native tools CAN author custom VFX, materials and reusable Blueprints, and generate bounded mesh geometry. Use byte_catalog kind=asset_types for schemas. External downloads, textures and animation generation, complex graph editing and arbitrary code are not available. Explain unsupported operations. Inspect existing animation/event components before adding a second owner. Prefer native editable components and event sheets."),
        ("vfx fireball projectile shooting particles effects", "For richer VFX start from editable layered presets Fireball, WaterBolt, LightningStrike, ClawSlash, HealingPulse, PoisonCloud, IceBurst or Shield. Layers support Smoke/Flame/Star/Arc/Lightning/Ripple sprites, SpriteResolution (32/64/128/256), Brightness, Dissolve, PatternStrength/PatternScale, RandomRotation and Horizontal/EmitterPlane rendering. VfxPlayer has Tint and Brightness; vfx.setTint and vfx.setBrightness control them. See byte_reference VFX-Authoring. Soft-depth particles, mesh particles and distortion are not implemented. For a traveling fireball: create_vfx saves a custom .bvfx with Loop=true, ParticleBudget around256, explicit MaxParticles per layer whose sum fits ParticleBudget, a small LocalSpace=true glowing core layer (Speed=0,Gravity=[0,0,0],orange/white colors) and LocalSpace=false trail/embers layers (short lifetime,drag,fade). Make a temporary scene template with VfxPlayer properties Effect=$asset:effectName,PlayOnStart=true,DestroyWhenFinished=false; add Projectile3D with suitable Radius and LifetimeComponent.LifetimeSeconds around3. save_blueprint captures that template, then delete_object the temporary scene template. Add/configure ProjectileLauncher3D on shooter with ProjectileBlueprint=$asset:blueprintName,ProjectileSpeed around18,Damage=10,FireCooldown=.25,MuzzleOffset outside shooter collider (ByteEngine forward is -Z). Add a native input.keyPressed {key:J} -> projectile.fire {} event to shooter. Do not add PlayerShooter3D unless automatic named Fire input is wanted. All of this fits one native apply batch using add_component.properties. ProjectileLauncher3D has a basic fallback without a Blueprint, but custom visuals need the authored prefab. It wraps Blueprint visuals under the moving projectile root, disables nested projectile movement and transfers root lifetime. Use native source reference if uncertain. Inspect existing fire/J rules before adding duplicates. Burst-only VFX is not a fired projectile."),
        ("material mesh model blueprint custom asset geometry", "Use create_material for reusable .bmat PBR/unlit/emissive parameters. create_vfx authors up to8 layers and lifetime curves in native .bvfx. save_blueprint exports a scene object plus children to an editable .byteblueprint, leaving the scene template until explicitly removed. create_mesh writes bounded indexed-triangle geometry as an importable OBJ; no model-generated code. Assets are immediately saved under project Assets and retained on scene Undo, never overwrite existing paths. Paths/aliases are returned; $asset:name can be used later in the same batch. Complex sculpted characters/textures/animations require external authoring and are outside these tools."),
        ("ui health text resources interface", "Use byte_catalog to find current UI, health, resource and text components/actions; do not invent APIs. Inspect UI objects and existing event sheets to identify who owns displayed values. Keep authored appearance in UI components and behavior in editable event rules. V1 exposes scalar/vector/enum, input and asset properties but not arbitrary collection editing. Explain when a requested layout or binding needs unsupported editor operations.")
    ];

    internal static object Search(string search)
    {
        var words = System.Text.RegularExpressions.Regex.Matches(search, @"[\w.]+").Select(m => m.Value).Where(w => w.Length > 2 && !new[] { "the", "and", "with", "need", "make", "from", "that", "this", "you", "for" }.Contains(w.ToLowerInvariant())).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
        if (words.Length == 0) return Guides.Select(g => new { topic = g.Topic }).ToArray();
        return Guides.Select(g => new { g.Topic, g.Guide, Score = words.Sum(w => (g.Topic.Contains(w, StringComparison.OrdinalIgnoreCase) ? 5 : 0) + (g.Guide.Contains(w, StringComparison.OrdinalIgnoreCase) ? 1 : 0)) })
            .Where(g => g.Score > 0).OrderByDescending(g => g.Score).Take(2).Select(g => new { topic = g.Topic, guide = g.Guide }).ToArray();
    }
}
